  // OPENAI_API_KEY. Reading both (gateway first) keeps the runner agnostic to the
  // mode while never carrying the secret in the argv JSON.
  const apiKey = process.env.AI_GATEWAY_API_KEY || process.env.OPENAI_API_KEY || '';

